#!/usr/bin/env bash
# Install/remove a verified per-kernel replacement generated by build.py.
set -Eeuo pipefail
directory=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
action=${1:-help}
case "$action" in
  help|--help|-h)
    echo 'Usage: manage.sh install|rollback|verify [kernel-release]'
    echo 'Defaults to the running kernel. Install/rollback do not reload Wi-Fi or reboot.'
    exit 0 ;;
  install|rollback|verify) ;;
  *) echo 'Unknown action. Use install, rollback, or verify.' >&2; exit 1 ;;
esac
if (( $# > 2 )); then echo 'Too many arguments.' >&2; exit 1; fi
kernel=${2:-$(uname -r)}
if [[ ! $kernel =~ ^[A-Za-z0-9][A-Za-z0-9._+-]*$ ]]; then
  echo 'Invalid kernel release.' >&2; exit 1
fi
release="$directory/release/$kernel"
module="$release/mt7925e.ko"
target="/usr/lib/modules/$kernel/updates/mt7925e.ko"
metadata=$(python3 - "$release/build-info.json" "$kernel" <<'PY'
import json, re, sys
with open(sys.argv[1]) as file:
    info = json.load(file)
if info['kernel'] != sys.argv[2]:
    sys.exit('Build metadata kernel mismatch')
values = [info['module_sha256'], info['module_srcversion'],
          info.get('kernel_package', 'linux-omarchy')]
patterns = [r'[a-f0-9]{64}', r'[A-F0-9]{1,24}', r'[A-Za-z0-9][A-Za-z0-9._+-]*']
if not all(re.fullmatch(pattern, value) for pattern, value in zip(patterns, values)):
    sys.exit('Invalid build metadata')
print('\n'.join(values))
PY
)
mapfile -t fields <<< "$metadata"
expected=${fields[0]}
expected_srcversion=${fields[1]}
kernel_package=${fields[2]}
if [[ $action == verify ]]; then
  echo "Running kernel: $(uname -r)"
  echo "Selected module: $(modinfo -n mt7925e)"
  echo "Selected source version: $(modinfo -F srcversion mt7925e)"
  loaded=$(cat /sys/module/mt7925e/srcversion 2>/dev/null || true)
  echo "Loaded source version: ${loaded:-not loaded}"
  echo "Expected patched source version: $expected_srcversion"
  if [[ $(uname -r) == "$kernel" && $loaded == "$expected_srcversion" ]]; then
    echo 'Patched module is active.'
  else
    echo 'Patched module is NOT active in the running kernel.'
    exit 2
  fi
  exit 0
fi
if (( EUID != 0 )); then exec sudo -- "$0" "$@"; fi
if [[ $(uname -r) != "$kernel" ]]; then
  echo "This build is only for $kernel; current kernel is $(uname -r). Rebuild first." >&2
  exit 1
fi
exec 9>/run/lock/mt7925-reset-fix.lock
flock -n 9 || { echo 'Another install/rollback is running.' >&2; exit 1; }
if [[ -e $target ]] && [[ $(sha256sum "$target" | cut -d' ' -f1) != "$expected" ]]; then
  echo "An unrelated override exists at $target; refusing to replace/remove it." >&2
  exit 1
fi
if [[ $action == install ]]; then
  [[ $(sha256sum "$module" | cut -d' ' -f1) == "$expected" ]] || {
    echo 'Staged module checksum does not match the verified build.' >&2; exit 1;
  }
  [[ $(modinfo -F vermagic "$module") == "$kernel "* ]] || {
    echo 'Kernel/module version mismatch.' >&2; exit 1;
  }
  if [[ -r /sys/kernel/security/lockdown ]] && ! grep -q '\[none\]' /sys/kernel/security/lockdown; then
    echo 'Kernel lockdown is enabled. This unsigned local module needs trusted signing first.' >&2
    exit 1
  fi
  install -Dm644 "$module" "$target"
else
  if [[ ! -f $target ]]; then echo 'No local override is installed.'; exit 0; fi
  rm -- "$target"
fi
depmod -a "$kernel"
if [[ $action == install && $(realpath -- "$(modinfo -n mt7925e)") != "$target" ]]; then
  echo 'Module lookup did not select the override. Removing it.' >&2
  rm -- "$target"
  depmod -a "$kernel"
  exit 1
fi

# Refresh the UKI/initramfs through the machine's existing Limine workflow,
# so a copy of the stock module in the boot image cannot override this fix.
boot_log=$(mktemp /var/tmp/mt7925-boot-refresh-XXXXXXXX.log)
boot_ok=true
/usr/bin/limine-mkinitcpio "$kernel_package" 2>&1 | tee "$boot_log" || boot_ok=false
# Some Limine versions return success even when an individual image failed.
if [[ $boot_ok == false ]] || python3 - "$boot_log" <<'PY'
import pathlib, re, sys
text = pathlib.Path(sys.argv[1]).read_text(errors='replace')
text = re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]', '', text)
sys.exit(0 if re.search(r'(?:^|\n)(?:==>\s*)?ERROR:', text) else 1)
PY
then
  echo 'Boot-image refresh failed. Do not reboot until it is repaired.' >&2
  echo "Build output: $boot_log" >&2
  echo "Retry: sudo limine-mkinitcpio $kernel_package" >&2
  echo "Or remove the override: sudo $0 rollback" >&2
  exit 1
fi
echo "Completed $action. Original packaged module was left untouched."
echo 'The running driver has not been reloaded. Reboot when your work is saved.'
echo "After reboot: $directory/manage.sh verify"
